export const HOME_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Brod: a cloud for the small software your team builds with AI</title>\n<meta name=\"description\" content=\"Your agent built it. Brod puts it online for your team: one step from code to a private address, with sign-in, roles, storage and rollback already there.\">\n<meta property=\"og:title\" content=\"Brod: a cloud for small software\">\n<meta property=\"og:description\" content=\"Your agent built it. Brod puts it online for your team, with sign-in, roles and storage already there.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"https://brod.sh/\">\n<meta property=\"og:image\" content=\"https://brod.sh/og.png\">\n<meta property=\"og:image:width\" content=\"1200\">\n<meta property=\"og:image:height\" content=\"630\">\n<meta property=\"og:image:alt\" content=\"Brod: an agent puts a shift swap tool online and shares it with the warehouse team.\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Brod: a cloud for small software\">\n<meta name=\"twitter:description\" content=\"Your agent built it. Brod puts it online for your team, with sign-in, roles and storage already there.\">\n<meta name=\"twitter:image\" content=\"https://brod.sh/og.png\">\n<link rel=\"canonical\" href=\"https://brod.sh/\">\n<meta name=\"theme-color\" content=\"#F1F5F2\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect x='3' y='13' width='22' height='13' rx='6.5' fill='%23F4B62E'/%3E%3Ccircle cx='21' cy='12' r='7' fill='%23F4B62E'/%3E%3C/svg%3E\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&family=JetBrains+Mono:wght@400;600&display=swap\">\n<!-- Google tag (gtag.js), on this public page only. Google Consent Mode v2: every kind of storage is denied until a\n     visitor accepts in the banner at the foot of the page, and the choice is remembered in this browser. -->\n<script>\n  window.dataLayer = window.dataLayer || [];\n  function gtag(){dataLayer.push(arguments);}\n  gtag('consent', 'default', { analytics_storage: 'denied', ad_storage: 'denied', ad_user_data: 'denied', ad_personalization: 'denied' });\n  try { if (localStorage.getItem('brod-analytics') === 'granted') gtag('consent', 'update', { analytics_storage: 'granted' }); } catch (e) {}\n  gtag('js', new Date());\n\n  gtag('config', 'G-CCYYNHQKR7');\n</script>\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-CCYYNHQKR7\"></script>\n<style>\n/* Layout: one left-aligned column on sage paper. The only loud things are the headline and the marigold action;\n   the hero is a transcript of the product's one moment, an agent putting an app online. */\n:root {\n  --paper: #F1F5F2; --card: #FBFCFB; --sunk: #E4EBE6; --ink: #13201A; --soft: #55655C; --line: #D3DDD6;\n  --go: #F4B62E; --go-ink: #221800; --go-edge: #C28A10; --green: #1E5B4A; --ok: #2B7A4B; --wait: #9A6208;\n  --code-bg: #14211B; --code-ink: #DCE7E0; --code-dim: #8FA398; --code-key: #F4B62E; --code-str: #9BD8B8;\n  --display: 'Bricolage Grotesque', 'Segoe UI', system-ui, sans-serif;\n  --body: 'Instrument Sans', 'Segoe UI', system-ui, sans-serif;\n  --mono: 'JetBrains Mono', ui-monospace, 'SF Mono', Menlo, monospace;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --paper: #101714; --card: #17201B; --sunk: #0B110E; --ink: #E7EEE9; --soft: #94A39A; --line: #29352F;\n    --go-edge: #A87608; --green: #7FD0B0; --ok: #6CC48D; --wait: #E3AD4E;\n    --code-bg: #0B110E; color-scheme: dark;\n  }\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--paper); color: var(--ink); font: 17px/1.55 var(--body); -webkit-font-smoothing: antialiased; }\nimg, svg { max-width: 100%; }\na { color: var(--green); text-underline-offset: 3px; }\n:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; border-radius: 4px; }\nh1, h2, h3 { font-family: var(--display); margin: 0; text-wrap: balance; }\nh1 { font-size: clamp(2.5rem, 6.6vw, 4.6rem); line-height: 1.02; letter-spacing: -0.035em; font-weight: 750; }\nh2 { font-size: clamp(1.7rem, 3.6vw, 2.5rem); line-height: 1.1; letter-spacing: -0.025em; font-weight: 700; }\nh3 { font-size: 1.12rem; line-height: 1.3; letter-spacing: -0.01em; font-weight: 650; }\np { margin: 0; }\ncode, .mono { font-family: var(--mono); font-size: 0.86em; }\n.wrap { width: min(100% - 40px, 1080px); margin-inline: auto; }\n.lede { font-size: clamp(1.08rem, 1.7vw, 1.28rem); color: var(--soft); max-width: 36em; }\n.soft { color: var(--soft); }\n\n/* header */\n.top { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-block: 22px; }\n.brand { display: inline-flex; align-items: center; gap: 10px; font: 750 1.45rem var(--display); letter-spacing: -0.03em; color: var(--ink); text-decoration: none; }\n.mark { width: 26px; height: 16px; border-radius: 9px; background: var(--go); box-shadow: 8px -6px 0 -2px var(--go); }\n.top nav { display: flex; align-items: center; gap: clamp(12px, 3vw, 30px); font-size: 0.95rem; }\n.top nav a { color: var(--soft); text-decoration: none; }\n.top nav a:hover { color: var(--ink); }\n.top nav .navlink { display: none; }\n@media (min-width: 720px) { .top nav .navlink { display: inline; } }\n\n/* buttons */\n.btn { display: inline-flex; align-items: center; justify-content: center; font: 650 1rem var(--body); padding: 12px 22px; border-radius: 12px; border: 1px solid var(--line); background: var(--card); color: var(--ink); text-decoration: none; cursor: pointer; }\n.btn:hover { border-color: var(--soft); }\n.btn.go { background: var(--go); color: var(--go-ink); border-color: var(--go-edge); box-shadow: 0 3px 0 var(--go-edge); font-weight: 700; }\n.btn.go:hover { transform: translateY(-1px); box-shadow: 0 4px 0 var(--go-edge); }\n.btn.go:active { transform: translateY(2px); box-shadow: 0 1px 0 var(--go-edge); }\n.btn.small { padding: 8px 16px; font-size: 0.92rem; border-radius: 10px; }\n.top nav a.btn { color: var(--ink); }\n\n/* hero */\n.hero { display: grid; gap: clamp(32px, 5vw, 64px); padding-block: clamp(28px, 6vw, 72px) clamp(48px, 8vw, 96px); align-items: center; }\n@media (min-width: 940px) { .hero { grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr); } }\n.hero-copy { display: flex; flex-direction: column; gap: 22px; min-width: 0; }\n.actions { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }\n.endpoint { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; font-size: 0.95rem; color: var(--soft); }\n.endpoint code { background: var(--sunk); color: var(--ink); padding: 6px 10px; border-radius: 8px; overflow-wrap: anywhere; }\n.copy { font: 600 0.85rem var(--body); background: none; border: 1px solid var(--line); border-radius: 8px; padding: 5px 10px; color: var(--ink); cursor: pointer; }\n.copy:hover { border-color: var(--soft); }\n.setup { font-size: 0.95rem; color: var(--soft); }\n.setup summary { cursor: pointer; color: var(--green); font-weight: 600; width: fit-content; }\n.setup[open] summary { margin-bottom: 14px; }\n.setup > p { margin-top: 12px; }\n.agents { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 16px 18px; display: flex; flex-direction: column; gap: 18px; }\n.agent h3 { font-size: 1rem; color: var(--ink); margin-bottom: 6px; }\n.agent ol { margin: 0; padding-left: 1.2em; display: flex; flex-direction: column; gap: 6px; }\n.agent code { background: var(--sunk); color: var(--ink); padding: 1px 6px; border-radius: 6px; overflow-wrap: anywhere; }\n.agent pre { margin-top: 8px; padding: 10px 12px; border-radius: 10px; font-size: 0.8rem; white-space: pre-wrap; overflow-wrap: anywhere; }\n.agents.tabbed { gap: 14px; }\n.agents.tabbed .agent h3 { display: none; }\n.tabs { display: flex; flex-wrap: wrap; gap: 6px; }\n.tabs button { font: 600 0.85rem var(--body); padding: 5px 11px; border-radius: 99px; border: 1px solid var(--line); background: none; color: var(--soft); cursor: pointer; }\n.tabs button[aria-selected=\"true\"] { background: var(--ink); color: var(--paper); border-color: var(--ink); }\n.demo { width: 100%; height: auto; border-radius: 20px; border: 1px solid var(--line); background: var(--sunk); box-shadow: 0 24px 60px -36px color-mix(in srgb, var(--green) 55%, transparent); }\n\n/* the transcript: the product's one moment */\n.talk { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: clamp(16px, 2.5vw, 24px); display: flex; flex-direction: column; gap: 12px; min-width: 0; box-shadow: 0 24px 60px -36px color-mix(in srgb, var(--green) 55%, transparent); }\n.talk-head { display: flex; justify-content: space-between; font-size: 0.82rem; color: var(--soft); }\n.said { align-self: flex-end; max-width: 88%; background: var(--ink); color: var(--paper); padding: 10px 14px; border-radius: 16px 16px 4px 16px; }\n.call { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 10px; align-items: baseline; font-size: 0.92rem; padding: 8px 12px; border-left: 2px solid var(--line); }\n.call code { color: var(--green); font-weight: 600; }\n.call span { color: var(--soft); overflow-wrap: anywhere; }\n.live { border: 1px solid var(--line); border-radius: 14px; overflow: hidden; background: var(--paper); }\n.bar { display: flex; align-items: center; gap: 8px; padding: 9px 12px; background: var(--sunk); font-family: var(--mono); font-size: 0.8rem; overflow-wrap: anywhere; }\n.bar i { width: 8px; height: 8px; border-radius: 50%; background: var(--ok); flex: none; }\n.live-body { padding: 14px; display: flex; flex-direction: column; gap: 10px; }\n.who { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; font-size: 0.93rem; }\n.chip { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; font-size: 0.82rem; padding: 3px 10px; border-radius: 99px; border: 1px solid currentColor; color: var(--wait); white-space: nowrap; }\n.chip.ok { color: var(--ok); }\n.talk [data-step] { transition: opacity .35s ease, transform .35s ease; }\n.talk.play [data-step].hide { opacity: 0; transform: translateY(6px); }\n@media (prefers-reduced-motion: reduce) { .talk [data-step] { transition: none; } .btn.go:hover, .btn.go:active { transform: none; } html { scroll-behavior: auto; } }\n\n/* sections */\nsection { padding-block: clamp(48px, 8vw, 96px); border-top: 1px solid var(--line); }\n.sec-head { display: flex; flex-direction: column; gap: 14px; margin-bottom: clamp(28px, 4vw, 48px); max-width: 44em; }\n\n/* the sequence is a real order, so it is numbered */\n.steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 28px; counter-reset: s; }\n@media (min-width: 760px) { .steps { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; } }\n.steps li { counter-increment: s; display: flex; flex-direction: column; gap: 8px; padding-top: 16px; border-top: 3px solid var(--ink); min-width: 0; }\n.steps li::before { content: counter(s); font: 750 2.2rem/1 var(--display); letter-spacing: -0.04em; }\n.steps li:last-child { border-color: var(--go); }\n.steps p { color: var(--soft); font-size: 0.98rem; }\n\n/* what every app gets: a spec sheet, name on the left, the real handle on the right */\n.spec { margin: 0; display: grid; }\n.spec > div { display: grid; gap: 4px 28px; padding-block: 18px; border-top: 1px solid var(--line); align-items: baseline; }\n.spec > div:last-child { border-bottom: 1px solid var(--line); }\n@media (min-width: 760px) { .spec > div { grid-template-columns: 13rem minmax(0, 1fr) auto; } }\n.spec dt { font: 650 1.08rem var(--display); }\n.spec dd { margin: 0; color: var(--soft); max-width: 34em; }\n.spec .handle { color: var(--green); font-family: var(--mono); font-size: 0.82rem; overflow-wrap: anywhere; }\n\n/* access: five modes on one scale, from closed to open */\n.ladder { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; }\n@media (min-width: 860px) { .ladder { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 16px; } }\n.ladder li { display: flex; flex-direction: column; gap: 6px; min-width: 0; }\n.ladder .meter { height: 10px; border-radius: 99px; background: var(--sunk); overflow: hidden; }\n.ladder .meter b { display: block; height: 100%; background: var(--green); border-radius: 99px; }\n.ladder p { color: var(--soft); font-size: 0.93rem; }\n.note { margin-top: 28px; padding: 18px 20px; border-radius: 14px; background: var(--card); border: 1px solid var(--line); max-width: 46em; }\n\n/* code */\n.two { display: grid; gap: clamp(24px, 4vw, 56px); align-items: center; }\n@media (min-width: 900px) { .two { grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr); } }\n.two .text { display: flex; flex-direction: column; gap: 16px; min-width: 0; }\npre { margin: 0; background: var(--code-bg); color: var(--code-ink); border-radius: 16px; padding: clamp(16px, 2.4vw, 24px); overflow-x: auto; font: 0.86rem/1.7 var(--mono); min-width: 0; }\npre .c { color: var(--code-dim); } pre .k { color: var(--code-key); } pre .s { color: var(--code-str); }\n\n/* pricing and what is next */\n.plans { display: grid; gap: 20px; }\n@media (min-width: 800px) { .plans { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } }\n.plan { border: 1px solid var(--line); border-radius: 18px; padding: clamp(20px, 3vw, 30px); background: var(--card); display: flex; flex-direction: column; gap: 14px; }\n.plan.next { background: transparent; border-style: dashed; }\n.plan ul { margin: 0; padding-left: 1.1em; color: var(--soft); display: flex; flex-direction: column; gap: 6px; }\n.price { font: 750 2.6rem/1 var(--display); letter-spacing: -0.04em; }\n.plan .btn { align-self: flex-start; margin-top: auto; }\n\n.close { text-align: left; display: flex; flex-direction: column; gap: 22px; align-items: flex-start; }\nfooter { border-top: 1px solid var(--line); padding-block: 28px 40px; display: flex; flex-wrap: wrap; gap: 12px 28px; justify-content: space-between; font-size: 0.9rem; color: var(--soft); }\nfooter a { color: var(--soft); }\nfooter nav { display: flex; flex-wrap: wrap; gap: 8px 22px; }\nfooter .linkish { font: inherit; color: var(--soft); background: none; border: 0; padding: 0; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }\n\n/* analytics consent: a small card in the corner; nothing is stored until Accept */\n.consent { position: fixed; left: 16px; right: 16px; bottom: 16px; z-index: 10; max-width: 25rem; display: flex; flex-direction: column; gap: 12px; padding: 14px 16px; background: var(--card); border: 1px solid var(--line); border-radius: 14px; font-size: 0.9rem; color: var(--soft); box-shadow: 0 18px 40px -24px color-mix(in srgb, var(--ink) 45%, transparent); }\n.consent[hidden] { display: none; }\n.consent-actions { display: flex; gap: 10px; justify-content: flex-end; }\n</style>\n</head>\n<body>\n\n<header class=\"wrap top\">\n  <a class=\"brand\" href=\"/\" aria-label=\"Brod home\"><span class=\"mark\" aria-hidden=\"true\"></span>Brod</a>\n  <nav aria-label=\"Main\">\n    <a class=\"navlink\" href=\"#how\">How it works</a>\n    <a class=\"navlink\" href=\"#apps\">What apps get</a>\n    <a class=\"navlink\" href=\"#teams\">Teams</a>\n    <a class=\"navlink\" href=\"#pricing\">Pricing</a>\n    <a href=\"/auth/signin\">Sign in</a>\n    <a class=\"btn go small\" href=\"/auth/signup\">Start free</a>\n  </nav>\n</header>\n\n<main>\n  <div class=\"wrap hero\">\n    <div class=\"hero-copy\">\n      <h1>Your agent built it. Brod puts it online for your team.</h1>\n      <p class=\"lede\">Brod is a cloud for small software: the tools you build with an AI agent for yourself or your team. One step from code to a private address, with sign-in, roles and storage already there.</p>\n      <div class=\"actions\">\n        <a class=\"btn go\" href=\"/auth/signup\">Start free</a>\n        <a class=\"btn\" href=\"#how\">See how it works</a>\n      </div>\n      <div class=\"endpoint\">\n        <span>Or connect your agent now:</span>\n        <code id=\"mcp-url\">https://brod.sh/mcp</code>\n        <button class=\"copy\" type=\"button\" data-copy=\"https://brod.sh/mcp\">Copy</button>\n      </div>\n      <details class=\"setup\" id=\"connect\">\n        <summary>Where do I paste it? Steps for Claude, Cursor, VS Code and others</summary>\n        <div class=\"agents\" id=\"agents\">\n          <div class=\"agent\" data-agent=\"Claude Code\">\n            <h3>Claude Code</h3>\n            <ol>\n              <li>In a terminal, run <code>claude mcp add --transport http brod https://brod.sh/mcp</code></li>\n              <li>Start <code>claude</code>, type <code>/mcp</code>, choose <b>brod</b> and sign in when the browser opens.</li>\n            </ol>\n          </div>\n          <div class=\"agent\" data-agent=\"Claude\">\n            <h3>Claude (web and desktop app)</h3>\n            <ol>\n              <li>Open <b>Settings</b>, then <b>Connectors</b>, then <b>Add custom connector</b>.</li>\n              <li>Name it Brod, paste <code>https://brod.sh/mcp</code> as the URL, and add it.</li>\n              <li>Press <b>Connect</b> and sign in when the browser opens.</li>\n            </ol>\n          </div>\n          <div class=\"agent\" data-agent=\"Cursor\">\n            <h3>Cursor</h3>\n            <ol>\n              <li>Open <code>~/.cursor/mcp.json</code> (or <b>Settings</b>, then <b>MCP</b>, then <b>Add new MCP server</b>) and add:<pre>{ \"mcpServers\": { \"brod\": { \"url\": \"https://brod.sh/mcp\" } } }</pre></li>\n              <li>Brod shows up in the MCP list; press <b>Connect</b> and sign in when the browser opens.</li>\n            </ol>\n          </div>\n          <div class=\"agent\" data-agent=\"VS Code\">\n            <h3>VS Code</h3>\n            <ol>\n              <li>Create <code>.vscode/mcp.json</code> in your project with:<pre>{ \"servers\": { \"brod\": { \"type\": \"http\", \"url\": \"https://brod.sh/mcp\" } } }</pre></li>\n              <li>Press <b>Start</b> above the entry, sign in when the browser opens, and use Brod in Copilot's agent mode.</li>\n            </ol>\n          </div>\n          <div class=\"agent\" data-agent=\"Other agents\">\n            <h3>Any other agent</h3>\n            <ol>\n              <li>Add a remote MCP server over HTTP with the address <code>https://brod.sh/mcp</code>.</li>\n              <li>When the browser opens, sign in with your email and pick the workspace the agent may use.</li>\n              <li>No browser sign-in in your agent? Make a token on your workspace's <b>Connections</b> page and send it as <code>Authorization: Bearer brod_&hellip;</code></li>\n            </ol>\n          </div>\n        </div>\n        <p class=\"soft\">Then ask: &ldquo;Put this online with Brod.&rdquo;</p>\n      </details>\n    </div>\n\n    <!-- The demo video: set data-video to its address (MP4, under 8 MB) and data-poster to a still from it. The video\n         loads after the page has, muted and looping, and replaces this example panel; until then the panel stays. -->\n    <div class=\"talk\" id=\"talk\" aria-label=\"Example: an agent deploying an app with Brod\" data-video=\"\" data-poster=\"\">\n      <div class=\"talk-head\"><span>Any agent that speaks MCP</span><span>Example</span></div>\n      <p class=\"said\" data-step>Put the shift swap tool online for the warehouse team.</p>\n      <div class=\"call\" data-step><code>get_workspace</code><span>Reads your groups and roles, so the app fits without being told.</span></div>\n      <div class=\"call\" data-step><code>deploy_app</code><span>Shift swap, version 1. Live in seconds.</span></div>\n      <div class=\"live\" data-step>\n        <div class=\"bar\"><i aria-hidden=\"true\"></i>https://shift-swap.harborops.brod.sh</div>\n        <div class=\"live-body\">\n          <div class=\"who\">\n            <span id=\"who-text\">Private. Only you can open it.</span>\n            <span class=\"chip\" id=\"who-chip\">Sharing waits for you</span>\n          </div>\n          <div class=\"who\">\n            <span class=\"soft\" id=\"ask-text\">The agent asked to share it with everyone in Harbor Ops.</span>\n            <button class=\"btn go small\" type=\"button\" id=\"confirm\">Confirm sharing</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <section id=\"how\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <h2>From a chat to your team in four moves</h2>\n        <p class=\"lede\">Building small tools got easy. Putting them somewhere safe, with the right people signed in, did not. Brod is the missing step.</p>\n      </div>\n      <ol class=\"steps\">\n        <li><h3>Connect once</h3><p>Add Brod to your agent as an MCP server. It works with any agent that speaks MCP. <a href=\"#connect\" data-open=\"connect\">Setup steps for your agent</a>.</p></li>\n        <li><h3>Ask</h3><p>&ldquo;Put this online for the team.&rdquo; The agent reads your workspace first, then deploys what it built.</p></li>\n        <li><h3>Get an address</h3><p>The app is live on HTTPS at its own address, and private to you until you say otherwise.</p></li>\n        <li><h3>Share with a click</h3><p>The agent proposes who gets in. You confirm. Teammates sign in once and find it on the workspace home page.</p></li>\n      </ol>\n    </div>\n  </section>\n\n  <section id=\"apps\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <h2>What every app gets without asking</h2>\n        <p class=\"lede\">No regions, instance sizes, access policies or login code. The parts every small tool needs are already attached.</p>\n      </div>\n      <dl class=\"spec\">\n        <div><dt>Sign-in</dt><dd>People sign in with an emailed link. Your app never sees a password and keeps no user table.</dd><span class=\"handle\">GET /_brod/me</span></div>\n        <div><dt>Roles and groups</dt><dd>Owner, editor and viewer by default. Define groups once in the workspace and every app uses them.</dd><span class=\"handle\">x-brod-role</span></div>\n        <div><dt>A database</dt><dd>Each app has its own SQLite database, with transactions.</dd><span class=\"handle\">env.DB.query(sql, params)</span></div>\n        <div><dt>Key-value and files</dt><dd>Small values and uploaded files, stored per app.</dd><span class=\"handle\">env.KV &nbsp; env.FILES</span></div>\n        <div><dt>Secrets</dt><dd>Write-only. Nobody can read one back after it is set, the agent included.</dd><span class=\"handle\">set_secret</span></div>\n        <div><dt>Versions and rollback</dt><dd>Every deploy is kept. Rolling back takes effect on the next request and rebuilds nothing.</dd><span class=\"handle\">rollback</span></div>\n        <div><dt>A safe deploy</dt><dd>A version whose server code does not start is refused, and the working version stays live.</dd><span class=\"handle\">deploy_app</span></div>\n        <div><dt>Logs</dt><dd>Console output and errors for recent requests, kept seven days, searchable by the agent that is fixing the bug.</dd><span class=\"handle\">get_logs</span></div>\n      </dl>\n    </div>\n  </section>\n\n  <section id=\"teams\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <h2>One workspace, one sign-in, every app</h2>\n        <p class=\"lede\">A workspace holds your team's people, groups and apps. Add a colleague to a group and they have the right access everywhere. Remove them and it ends everywhere.</p>\n      </div>\n      <ol class=\"ladder\" aria-label=\"Access modes, from most closed to most open\">\n        <li><div class=\"meter\"><b style=\"width:20%\"></b></div><h3>Private</h3><p>Only the app's owner and workspace admins.</p></li>\n        <li><div class=\"meter\"><b style=\"width:40%\"></b></div><h3>People</h3><p>Only the people and groups you give a role.</p></li>\n        <li><div class=\"meter\"><b style=\"width:60%\"></b></div><h3>Workspace</h3><p>Everyone in your workspace.</p></li>\n        <li><div class=\"meter\"><b style=\"width:80%\"></b></div><h3>Signed in</h3><p>Anyone who signs in.</p></li>\n        <li><div class=\"meter\"><b style=\"width:100%\"></b></div><h3>Public</h3><p>Anyone, with no sign-in.</p></li>\n      </ol>\n      <p class=\"note\"><strong>An agent cannot open an app up by itself.</strong> Narrowing access applies at once. Widening it, or inviting someone, waits for a person to confirm.</p>\n    </div>\n  </section>\n\n  <section id=\"code\">\n    <div class=\"wrap two\">\n      <div class=\"text\">\n        <h2>An app is a folder. Server code is one file.</h2>\n        <p class=\"lede\">Static files are served as they are. Add a <code>_worker.js</code> and it answers every other request, with the signed-in person in the headers and the app's storage on <code>env</code>.</p>\n        <p class=\"soft\">Your agent already knows this. Brod tells it when it connects.</p>\n      </div>\n<pre aria-label=\"Example server code for a Brod app\"><span class=\"c\">// _worker.js</span>\n<span class=\"k\">export default</span> {\n  <span class=\"k\">async</span> fetch(request, env) {\n    <span class=\"k\">const</span> role = request.headers.get(<span class=\"s\">'x-brod-role'</span>);\n    <span class=\"k\">if</span> (role !== <span class=\"s\">'editor'</span> &amp;&amp; role !== <span class=\"s\">'owner'</span>)\n      <span class=\"k\">return new</span> Response(<span class=\"s\">'Ask an editor'</span>, { status: 403 });\n\n    <span class=\"k\">const</span> open = <span class=\"k\">await</span> env.DB.query(\n      <span class=\"s\">'SELECT * FROM swaps WHERE status = ?'</span>, [<span class=\"s\">'open'</span>]);\n    <span class=\"k\">return</span> Response.json(open);\n  }\n};</pre>\n    </div>\n  </section>\n\n  <section id=\"pricing\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <h2>Free to start. A plan, never a bill per app.</h2>\n        <p class=\"lede\">Brod is priced as a plan for a workspace, with room for a number of apps and people. Deploying inside it never adds a charge.</p>\n      </div>\n      <div class=\"plans\">\n        <div class=\"plan\">\n          <div class=\"price\">Free</div>\n          <ul>\n            <li>10 running apps. Paused apps do not count.</li>\n            <li>10 people in the workspace</li>\n            <li>250 MB of storage</li>\n            <li>Sign-in, roles, database, secrets, rollback and logs</li>\n          </ul>\n          <a class=\"btn go\" href=\"/auth/signup\">Start free</a>\n        </div>\n        <div class=\"plan next\">\n          <h3>On the way</h3>\n          <ul>\n            <li>Larger plans for bigger teams, with more apps and people.</li>\n            <li>A marketplace: list an app you built, and other teams install a private copy into their own workspace, with their own data and sign-in.</li>\n          </ul>\n          <p class=\"soft\">Neither is available yet.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"wrap close\">\n      <h2>The next tool your agent builds can be in front of your team today.</h2>\n      <div class=\"actions\">\n        <a class=\"btn go\" href=\"/auth/signup\">Start free</a>\n        <button class=\"copy\" type=\"button\" data-copy=\"https://brod.sh/mcp\">Copy the MCP address</button>\n      </div>\n    </div>\n  </section>\n</main>\n\n<footer class=\"wrap\">\n  <span>© 2026 Brod</span>\n  <nav aria-label=\"Footer\">\n    <a href=\"/auth/signin\">Sign in</a>\n    <a href=\"#how\">How it works</a>\n    <a href=\"#pricing\">Pricing</a>\n    <button class=\"linkish\" type=\"button\" id=\"consent-open\">Cookie settings</button>\n  </nav>\n</footer>\n\n<div class=\"consent\" id=\"consent\" role=\"region\" aria-label=\"Analytics cookies\" hidden>\n  <p>May we use Google Analytics cookies to count visits and see how people find Brod? Nothing is stored unless you accept.</p>\n  <div class=\"consent-actions\">\n    <button class=\"btn small\" type=\"button\" data-consent=\"denied\">Decline</button>\n    <button class=\"btn small\" type=\"button\" data-consent=\"granted\">Accept</button>\n  </div>\n</div>\n\n<script>\n// Copy buttons: say what happened, and fall back to selecting the text.\ndocument.querySelectorAll('[data-copy]').forEach(function (b) {\n  var label = b.textContent;\n  b.addEventListener('click', function () {\n    var done = function () { b.textContent = 'Copied'; setTimeout(function () { b.textContent = label; }, 1600); };\n    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(b.dataset.copy).then(done, select);\n    else select();\n    function select() { var el = document.getElementById('mcp-url'); if (!el) return; var r = document.createRange(); r.selectNodeContents(el); var s = getSelection(); s.removeAllRanges(); s.addRange(r); }\n  });\n});\n\n// Setup steps: one agent at a time once script runs; without it every agent's steps are listed under its own heading.\n(function () {\n  var box = document.getElementById('agents'), agents = box.querySelectorAll('.agent'), tabs = document.createElement('div');\n  tabs.className = 'tabs'; tabs.setAttribute('role', 'tablist'); tabs.setAttribute('aria-label', 'Your agent');\n  agents.forEach(function (a, i) {\n    var b = document.createElement('button');\n    b.type = 'button'; b.textContent = a.dataset.agent; b.setAttribute('role', 'tab'); b.id = 'agent-tab-' + i;\n    a.setAttribute('role', 'tabpanel'); a.setAttribute('aria-labelledby', b.id);\n    b.addEventListener('click', function () { show(i); });\n    tabs.appendChild(b);\n  });\n  function show(n) {\n    agents.forEach(function (a, i) { a.hidden = i !== n; tabs.children[i].setAttribute('aria-selected', String(i === n)); });\n  }\n  box.prepend(tabs); box.classList.add('tabbed'); show(0);\n  document.querySelectorAll('[data-open]').forEach(function (l) {\n    l.addEventListener('click', function () { document.getElementById(l.dataset.open).open = true; });\n  });\n})();\n\n// The demo video, once it has an address: it loads after everything else, so the text is never kept waiting.\n(function () {\n  var talk = document.getElementById('talk'), src = talk.dataset.video;\n  if (!src) return;\n  addEventListener('load', function () {\n    var v = document.createElement('video'), still = matchMedia('(prefers-reduced-motion: reduce)').matches;\n    v.className = 'demo'; v.muted = true; v.loop = true; v.playsInline = true; v.preload = 'auto';\n    v.setAttribute('muted', ''); v.setAttribute('playsinline', '');\n    v.setAttribute('aria-label', 'Demo: an agent puts an app online with Brod and shares it with a team');\n    if (talk.dataset.poster) v.poster = talk.dataset.poster;\n    if (still) v.controls = true; else v.autoplay = true;\n    v.src = src;\n    talk.replaceWith(v);\n  });\n})();\n\n// The transcript plays once on load. Everything is already in the page, so nothing is lost without script or motion.\n(function () {\n  var talk = document.getElementById('talk'), steps = talk.querySelectorAll('[data-step]');\n  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) {\n    steps.forEach(function (s) { s.classList.add('hide'); });\n    talk.classList.add('play');\n    steps.forEach(function (s, i) { setTimeout(function () { s.classList.remove('hide'); }, 350 + i * 650); });\n  }\n  var btn = document.getElementById('confirm');\n  btn.addEventListener('click', function () {\n    document.getElementById('who-text').textContent = 'Everyone in Harbor Ops, after signing in.';\n    var chip = document.getElementById('who-chip'); chip.textContent = 'Shared'; chip.classList.add('ok');\n    document.getElementById('ask-text').textContent = 'Confirmed by you. Teammates see it on the workspace home page.';\n    btn.remove();\n  });\n})();\n\n// Analytics consent: ask once, remember the answer in this browser, and let \"Cookie settings\" ask again.\n(function () {\n  var box = document.getElementById('consent'), KEY = 'brod-analytics', saved = null;\n  try { saved = localStorage.getItem(KEY); } catch (e) {}\n  if (saved !== 'granted' && saved !== 'denied') box.hidden = false;\n  box.querySelectorAll('[data-consent]').forEach(function (b) {\n    b.addEventListener('click', function () {\n      var choice = b.dataset.consent;\n      gtag('consent', 'update', { analytics_storage: choice });\n      try { localStorage.setItem(KEY, choice); } catch (e) {}\n      var hadFocus = box.contains(document.activeElement);\n      box.hidden = true;\n      if (hadFocus) document.getElementById('consent-open').focus({ preventScroll: true });\n    });\n  });\n  document.getElementById('consent-open').addEventListener('click', function () {\n    box.hidden = false;\n    box.querySelector('[data-consent]').focus();\n  });\n})();\n</script>\n</body>\n</html>\n";
export const HOME_ETAG = "\"8cfb8c9de832ae6e\"";
export const OG_PNG_BASE64 = "";
export const OG_PNG_ETAG = "\"fedddcdfe3dd1c90\"";
